mapper.select:
WITH TEMP AS (
SELECT #{prod.embryoCode} EMBRYO_CODE, #{prod.bomDataVersion} EMBRYO_VERSION FROM DUAL
) SELECT T.EMBRYO_CODE, T.EMBRYO_VERSION FROM TEMP T INNER JOIN T_CONSTRUCTION_VERSION_INFO C ON C.EMBRYO_CODE = T.EMBRYO_CODE AND C.EMBRYO_VERSION = T.EMBRYO_VERSION AND C.DEL_FLAG = '0' GROUP BY T.EMBRYO_CODE, T.EMBRYO_VERSION

WITH TEMP AS (
SELECT #{embryoCode} EMBRYO_CODE FROM DUAL
) SELECT T.EMBRYO_CODE, MAX(T.EMBRYO_VERSION) EMBRYO_VERSION FROM T_CONSTRUCTION_VERSION_INFO T WHERE T.DEL_FLAG = '0' AND T.EMBRYO_CODE IN (SELECT EMBRYO_CODE FROM TEMP) GROUP BY T.EMBRYO_CODE HAVING COUNT(1) = 1

mapper.update:
INSERT INTO t_product_construction_info a (a.id, a.sap_code, a.embryo_code, a.embryo_version, a.cons_type, a.dimension, a.spec_desc, a.nose_width, a.flip_disc_diameter, a.section_width, a.fit_drum_perimeter, a.chuck_diameter, a.stretch_width, a.qualitative_width, a.embryo_circle, a.tire_fabric_code1, a.tire_fabric_sap1, a.tire_fabric1_version, a.tire_fabric_craft1, a.tire_fabric_code2, a.tire_fabric_sap2, a.tire_fabric2_version, a.tire_fabric_craft2, a.tire_fabric_code3, a.tire_fabric_sap3, a.tire_fabric3_version, a.tire_fabric_craft3, a.original_line_code, a.cord_spec, a.cord_sap, a.cord_version, a.reinforce_seal_glue, a.inside_rubber, a.inside_code, a.inside_sap, a.inside_version, a.inside_craft, a.sidewall_code, a.sidewall_sap, a.sidewall_version, a.sidewall_craft, a.sidewall_mouth_plate, a.sidewall_center, a.sidewall_length, a.sidewall_rubber, a.sidewall_weight, a.sidewall_wearp_rubber_weight, a.support_code, a.support_rubber_code, a.support_length, a.bead_code, a.bead_sap, a.bead_version, a.bead_arrange, a.bead_type, a.tire_ring_code, a.tire_ring_sap, a.tire_ring_version, a.apex_code, a.hexagon_rubber_code, a.hexagon_mouth_plate, a.hexagon_rubber_dimension, a.apex_weight, a.belt_code1, a.belt_sap1, a.belt1_version, a.belt_craft1, a.belt_side_rubber1, a.belt_rubber1, a.belt_code2, a.belt_sap2, a.belt2_version, a.belt_craft2, a.belt_side_rubber2, a.belt_rubber2, a.belt_cutting_angle, a.article_crown_spec, a.article_crown_sap, a.article_crown_version, a.article_crown_code, a.tread_code, a.tread_sap, a.tread_version, a.tread_shoulder_width, a.tread_shoulder_jwidth, a.tread_shoulder_length, a.tread_rubber_category, a.tire_crown_up_width_weight, a.tire_crown_down_width_weight, a.tire_wing_width_weight, a.primer_weight, a.conducting_resin_weight, a.tread_mouth_plate, a.create_by, a.create_time, a.update_by, a.update_time, a.del_flag, a.remark, a.production_stage, a.TIRE_FABRIC_SIDE_RUBBER) WITH temp_code AS (
SELECT #{embryoCode} embryoCode FROM dual
) SELECT SEQ_CONSTRUCTION_INFO.NEXTVAL, sap_code, embryo_code, embryo_version, cons_type, dimension, spec_desc, nose_width, flip_disc_diameter, section_width, fit_drum_perimeter, chuck_diameter, stretch_width, qualitative_width, embryo_circle, tire_fabric_code1, tire_fabric_sap1, tire_fabric1_version, tire_fabric_craft1, tire_fabric_code2, tire_fabric_sap2, tire_fabric2_version, tire_fabric_craft2, tire_fabric_code3, tire_fabric_sap3, tire_fabric3_version, tire_fabric_craft3, original_line_code, cord_spec, cord_sap, cord_version, reinforce_seal_glue, inside_rubber, inside_code, inside_sap, inside_version, inside_craft, sidewall_code, sidewall_sap, sidewall_version, sidewall_craft, sidewall_mouth_plate, sidewall_center, sidewall_length, sidewall_rubber, sidewall_weight, sidewall_wearp_rubber_weight, support_code, support_rubber_code, support_length, bead_code, bead_sap, bead_version, bead_arrange, bead_type, tire_ring_code, tire_ring_sap, tire_ring_version, apex_code, hexagon_rubber_code, hexagon_mouth_plate, hexagon_rubber_dimension, apex_weight, belt_code1, belt_sap1, belt1_version, belt_craft1, belt_side_rubber1, belt_rubber1, belt_code2, belt_sap2, belt2_version, belt_craft2, belt_side_rubber2, belt_rubber2, belt_cutting_angle, article_crown_spec, article_crown_sap, article_crown_version, article_crown_code, tread_code, tread_sap, tread_version, tread_shoulder_width, tread_shoulder_jwidth, tread_shoulder_length, tread_rubber_category, tire_crown_up_width_weight, tire_crown_down_width_weight, tire_wing_width_weight, primer_weight, conducting_resin_weight, tread_mouth_plate, create_by, now() create_time, update_by, now() update_time, del_flag, remark, production_stage, TIRE_FABRIC_SIDE_RUBBER FROM t_construction_version_info t WHERE t.embryo_code IN (SELECT embryoCode FROM temp_code) AND not exists (SELECT 0 FROM t_construction_version_info tt WHERE tt.embryo_code = t.embryo_code AND tt.embryo_version = t.embryo_version AND tt.del_flag = '0' AND (nvl(tt.update_time, tt.create_time) > nvl(t.update_time, t.create_time) or nvl(tt.update_time, tt.create_time) = nvl(t.update_time, t.create_time) and tt.id > t.id)) AND NOT EXISTS (SELECT 1 FROM t_product_construction_info tt WHERE tt.embryo_code = t.embryo_code AND tt.embryo_version = t.embryo_version AND tt.del_flag = '0' ) AND t.del_flag = '0'
